package com.loops;

import java.util.Scanner;

public class Task2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc = new Scanner(System.in);
        int range = sc.nextInt();
        int counter = 1;

        while(counter <= range){
            System.out.println(counter + " ");
            counter++;
        }
        System.out.println();
   

	}

}
